import type { EngineInterface, Register } from 'claude-code'

import {
  CLIPBOARD_CANDIDATES,
  clipboardMatches,
  expand,
  findTags,
  splitCommand,
  tooLong,
} from './paste'

const POLL_MS = 250

async function readClipboard(
  $: EngineInterface,
  argv: readonly string[],
): Promise<string | undefined> {
  const r = await $.process.run(argv, { timeoutMs: 2000 }).catch(() => undefined)
  return r !== undefined && r.exitCode === 0 ? r.stdout : undefined
}

async function findClipboard(
  $: EngineInterface,
  custom: string[],
): Promise<readonly string[] | undefined> {
  const list = custom.length > 0 ? [custom] : CLIPBOARD_CANDIDATES
  for (const argv of list) {
    if ((await readClipboard($, argv)) !== undefined) return argv
  }
  return undefined
}

export const register: Register = (on, options) => {
  const custom = splitCommand(options?.clipboardCommand)
  const maxLines = typeof options?.maxLines === 'number' ? options.maxLines : 0
  const seen = new Set<number>() // tag numbers already tried: never retry a mismatch
  let argv: readonly string[] | undefined
  let isOn = true
  let isBusy = false

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'paste-inline',
      description: 'Turn inline paste expansion on or off (/paste-inline on|off)',
    })

    $.clock.every(POLL_MS, async () => {
      if (!isOn || isBusy) return
      isBusy = true
      try {
        const box = await $.prompt.read()
        const fresh = findTags(box.text).filter(t => !seen.has(t.id))
        if (fresh.length === 0) return
        argv = argv ?? (await findClipboard($, custom))
        if (argv === undefined) {
          for (const t of fresh) seen.add(t.id)
          return
        }
        // Only the newest tag can be what the clipboard holds now.
        const tag = fresh[fresh.length - 1]
        for (const t of fresh) seen.add(t.id)
        const clip = await readClipboard($, argv)
        if (clip === undefined || !clipboardMatches(tag, clip) || tooLong(clip, maxLines)) return
        const now = await $.prompt.read()
        if (!now.text.includes(tag.raw)) return
        await $.prompt.fill({ text: expand(now.text, tag, clip), mode: 'replace' })
      } finally {
        isBusy = false
      }
    })

    return next(e)
  })

  on('command.run', { command: 'paste-inline' }, async (_$, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'off') isOn = false
    else if (arg === 'on') isOn = true
    else isOn = !isOn
    return { text: `paste-inline is ${isOn ? 'on' : 'off'}.` }
  })
}

