// Pure helpers for finding Claude Code's paste tags and matching them to the clipboard.

export type Tag = { raw: string; id: number; lines: number }

const TAG = /\[Pasted text #(\d+)(?: \+(\d+) lines)?\]/g

export function findTags(draft: string): Tag[] {
  const out: Tag[] = []
  for (const m of draft.matchAll(TAG)) {
    out.push({ raw: m[0], id: Number(m[1]), lines: m[2] === undefined ? 0 : Number(m[2]) })
  }
  return out
}

const newlines = (s: string): number => (s.match(/\n/g) ?? []).length

/** Strips what clipboard tools add: CRLF and one trailing newline. */
export function normalize(clip: string): string {
  return clip.replace(/\r\n/g, '\n').replace(/\n$/, '')
}

/**
 * The tag counts the pasted text's lines; clipboards differ by a trailing newline,
 * so a difference of one is tolerated. An empty clipboard never matches.
 */
export function clipboardMatches(tag: Tag, clip: string): boolean {
  const text = normalize(clip)
  if (text.trim() === '') return false
  const n = newlines(text)
  return Math.abs(n - tag.lines) <= 1
}

export function tooLong(clip: string, maxLines: number): boolean {
  return maxLines > 0 && newlines(normalize(clip)) + 1 > maxLines
}

export function expand(draft: string, tag: Tag, clip: string): string {
  const at = draft.indexOf(tag.raw)
  if (at < 0) return draft
  return draft.slice(0, at) + normalize(clip) + draft.slice(at + tag.raw.length)
}

export function splitCommand(s: unknown): string[] {
  return typeof s === 'string' ? s.split(/\s+/).filter(x => x !== '') : []
}

export const CLIPBOARD_CANDIDATES: readonly string[][] = [
  ['pbpaste'],
  ['wl-paste', '--no-newline'],
  ['xclip', '-selection', 'clipboard', '-o'],
  ['xsel', '--clipboard', '--output'],
  ['powershell.exe', '-NoProfile', '-Command', 'Get-Clipboard -Raw'],
]

