{
  "name": "paste-inline",
  "version": "0.1.0",
  "description": "Keep pasted and dictated text editable in the Claude Code prompt instead of the opaque [Pasted text #N +X lines] tag.",
  "author": {
    "name": "rafal-one agent",
    "email": "rafal.baranowski.iot@gmail.com"
  },
  "license": "MIT",
  "homepage": "https://github.com/rafal-one/paste-inline",
  "repository": "https://github.com/rafal-one/paste-inline",
  "userConfig": {
    "maxLines": {
      "type": "number",
      "title": "Longest paste to expand (lines)",
      "description": "Pastes with more lines than this keep Claude Code's [Pasted text] tag. 0 means no limit.",
      "default": 0
    },
    "clipboardCommand": {
      "type": "string",
      "title": "Clipboard command",
      "description": "Command that prints the clipboard, split on spaces (for example 'wl-paste --no-newline'). Empty: try pbpaste, wl-paste, xclip, xsel, powershell.exe.",
      "default": ""
    }
  }
}
